def free_intervals(busy, day_start, day_end):
    # busy sorted intervals
    merged=[]
    for start,end in sorted(busy):
       if not merged or start > merged[-1][1]:
          merged.append([start,end])
       else:
          merged[-1][1]=max(merged[-1][1], end)
    free=[]
    cur=day_start
    for s,e in merged:
       if cur < s:
           free.append((cur, s))
       cur=max(cur,e)
    if cur < day_end:
       free.append((cur, day_end))
    return free

def intersect_intervals(list_of_free):
    free = list_of_free[0]
    for other in list_of_free[1:]:
        new=[]
        i=j=0
        while i<len(free) and j<len(other):
            s=max(free[i][0], other[j][0])
            e=min(free[i][1], other[j][1])
            if s<e: new.append((s,e))
